    args = struct.unpack_from("<6Q", req, 32)
    name = sysname(nr)
    size = 0
    end = 0
    if name == "mmap":
        size = args[1]
    elif name == "mremap":
        size = args[2]
    elif name == "brk" and args[0]:
        end = heap_end(pid)
        size = args[0] - end if end and args[0] > end else 0
        if size:
            size = max(size, thr)
    k, seq = read_arm()
    if seq != state["seq"] or not k:
        state.update(seq=seq, count=0, injected=0, oom=False)
    counted = bool(k) and size >= thr
    fail = False
    if counted:
        state["count"] += 1
        if state["count"] == k:
            state["oom"] = True
        fail = state["oom"]
        if fail:
            state["injected"] += 1
        open(count_path, "w").write("%d %d %s %d\n" % (state["count"], state["injected"], name, size))
    if fail:
