        for line in open("/proc/%d/maps" % pid):
            if line.rstrip().endswith("[heap]"):
                return int(line.split("-")[1].split()[0], 16)
    except OSError:
        pass
    return 0

def read_arm():
    try:
        k, seq = open(arm_path).read().split()
        return int(k), seq
    except (OSError, ValueError):
        return 0, "0"

state = {"seq": None, "count": 0, "injected": 0, "oom": False}
status = None
while status is None:
    done, wait = os.waitpid(child, os.WNOHANG)
    if done:
        status = wait
        break
    ready, _, _ = select.select([listener], [], [], 0.05)
    if not ready:
        continue
    req = bytearray(80)
    try:
        fcntl.ioctl(listener, NOTIF_RECV, req, True)
    except OSError as exc:
        if exc.errno in (errno.ENOENT, errno.EINTR):
            continue
        raise
    ident, pid, _f, nr, _a, _ip = struct.unpack_from("<QIIiIQ", req)
    args = struct.unpack_from("<6Q", req, 32)
    name = sysname(nr)
    size = 0
    end = 0
    if name == "mmap":
        size = args[1]
    elif name == "mremap":
        size = args[2]
    elif name == "brk" and args[0]:
        end = heap_end(pid)
        size = args[0] - end if end and args[0] > end else 0
        if size:
            size = max(size, thr)
    k, seq = read_arm()
    if seq != state["seq"] or not k:
        state.update(seq=seq, count=0, injected=0, oom=False)
    counted = bool(k) and size >= thr
    fail = False
    if counted:
        state["count"] += 1
        if state["count"] == k:
            state["oom"] = True
        fail = state["oom"]
        if fail:
            state["injected"] += 1
        open(count_path, "w").write("%d %d %s %d\n" % (state["count"], state["injected"], name, size))
    if fail:
        if name == "brk":
            resp = struct.pack("<QqiI", ident, end, 0, 0)
        else:
            resp = struct.pack("<QqiI", ident, 0, -errno.ENOMEM, 0)
    else:
        resp = struct.pack("<QqiI", ident, 0, 0, FLAG_CONTINUE)
    try:
        fcntl.ioctl(listener, NOTIF_SEND, resp)
    except OSError as exc:
        if exc.errno != errno.ENOENT:
            raise
sys.exit(os.waitstatus_to_exitcode(status) if os.WIFEXITED(status) else 128 + os.WTERMSIG(status))
